                                                                                                                                                                                                           
  CREATE TABLE "STS_ROLE"                                                                                                                                                                        
   (	"ROLE_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"ROLE_NAME" VARCHAR2(100),                                                                                                                                                                                
	"HOME_PAGE" NUMBER(20,0),                                                                                                                                                                                 
	"ROLE_TYPE" VARCHAR2(100),                                                                                                                                                                                
	"DEFAULT_ROLE" NUMBER(20,0) DEFAULT 0,                                                                                                                                                                    
	"ROLE_LEVEL" NUMBER(20,0),                                                                                                                                                                                
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1,                                                                                                                                                                        
	"SORT_NUM" NUMBER(20,0),                                                                                                                                                                                  
	"PERMISSION_RANGE" VARCHAR2(2000),                                                                                                                                                                        
	"TENANT_ID" NUMBER(20,0),                                                                                                                                                                                 
	"REMARK" VARCHAR2(500),                                                                                                                                                                                   
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                
	"CREATION_DATE" DATE DEFAULT sysdate,                                                                                                                                                                     
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                
	"UPDATE_DATE" DATE DEFAULT sysdate,                                                                                                                                                                       
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0,                                                                                                                                                                         
	 PRIMARY KEY ("ROLE_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                      
   ) ;                                                                                                                                                                                                     

